     },

     /// The run stopped without a final output (for example, a deferral or a
     /// turn checkpoint stop).
     #[error("run did not complete")]
     Incomplete {
         /// Why the run stopped.
         stop_reason: crate::StopReason,
     },

+    /// The model turn did not end cleanly (`Length`, `ContentFilter`, or a
+    /// stream with no `Finish`), so the loop did not run its tool calls.
+    #[error("{}", tool_calls_not_run_text(.finish_reason, .tool_names))]
+    #[non_exhaustive]
+    ToolCallsNotRun {
+        /// How the turn ended, or `None` when the stream ended with no
+        /// `Finish` event.
+        finish_reason: Option<crate::FinishReason>,
+        /// Names of the tool calls the loop did not run.
+        tool_names: Vec<String>,
+    },
+
     /// Escape hatch.
     #[error(transparent)]
     Other(#[from] anyhow::Error),
 }

+/// Build the `Display` text of [`AgentError::ToolCallsNotRun`].
+fn tool_calls_not_run_text(
+    finish_reason: &Option<crate::FinishReason>,
+    tool_names: &[String],
+) -> String {
+    let ended = match finish_reason {
+        Some(r) => format!("the model turn ended with {r:?}"),
+        None => "the model stream ended with no finish reason".to_string(),
+    };
+    format!(
+        "{ended}, so the tool calls were not run: {}",
+        crate::model::cap_names(tool_names)
+    )
+}
+
 /// Out-of-band carrier for a run's terminal structured [`AgentError`].
 ///
 /// The [`crate::AgentEvent`] stream stays string-based
 /// ([`crate::AgentEvent::RunFailed`]` { error: String }`) so it remains `Clone`
 /// and snapshot-stable; the structured error rides this side-channel instead.
 /// One slot lives on each [`RunContext`]; the agent records into it at the
 /// moment of failure and a [`crate::Runner`] (or
 /// [`crate::RunResultStreaming::collect`]) reads it **after the event stream is
 /// fully drained** — see [`crate::RunResultStreaming::collect`] for why the
 /// read must come after draining.
@@ -2217,10 +2244,55 @@ mod terminal_tests {
             .into_iter()
             .filter(AgentEvent::is_terminal)
             .collect();
         assert_eq!(
             terminal.len(),
